1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  /** Zero-based index of the quote step that created the policy. */
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export type Step = QuoteStep | ClaimStep;
31	
32	export interface Customer {
33	  yearsWithMHPCO: number;
34	}
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export interface ScenarioResults {
51	  results: (QuoteResult | ClaimResult)[];
52	}
53	
54	const PROCESSING_FEE = 5;
55	const FIRST_INSURANCE_SURCHARGE = 0.1;
56	const CURSE_SURCHARGE = 0.5;
57	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const LOYALTY_DISCOUNT = 0.2;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
62	
63	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
64	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	const BASE_PREMIUMS: Record<string, number> = {
67	  sword: 100,
68	  amulet: 60,
69	  staff: 80,
70	  potion: 40,
71	  rune: 25,
72	  moonstone: 25,
73	};
74	
75	const INSURANCE_VALUES: Record<string, number> = {
76	  sword: 1000,
77	  amulet: 600,
78	  staff: 800,
79	  potion: 400,
80	  rune: 250,
81	  moonstone: 250,
82	};
83	
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLIER = 2;
86	
87	const COMPONENT_TYPES = ["rune", "moonstone"];
88	const BLOCK_SIZE = 3;
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
92	
93	const countByType = (items: Item[]): Map<string, number> => {
94	  const counts = new Map<string, number>();
95	
96	  for (const item of items) {
97	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
98	  }
99	
100	  return counts;
101	};
102	
103	/** Exactly BLOCK_SIZE alike components form a building block. */
104	const formsBuildingBlock = (type: string, count: number): boolean =>
105	  isComponent(type) && count === BLOCK_SIZE;
106	
107	const itemBasePremium = (type: string): number => BASE_PREMIUMS[type];
108	
109	/** Alike items are priced together so a building block can be recognised. */
110	const groupBasePremium = (type: string, count: number): number =>
111	  formsBuildingBlock(type, count)
112	    ? BLOCK_BASE_PREMIUM
113	    : count * itemBasePremium(type);
114	
115	/** The policy base premium is the sum of the base premiums of its items. */
116	const policyBasePremium = (items: Item[]): number =>
117	  [...countByType(items)].reduce(
118	    (total, [type, count]) => total + groupBasePremium(type, count),
119	    0,
120	  );
121	
122	const isCursed = (item: Item): boolean => item.cursed === true;
123	
124	const isHighlyEnchanted = (item: Item): boolean =>
125	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
126	
127	/**
128	 * Item-specific surcharges stack additively, as fractions of the item's base
129	 * premium.
130	 */
131	const itemSurchargeRate = (item: Item): number =>
132	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
133	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
134	
135	/**
136	 * Item-specific modifiers apply to the base premium of the affected item,
137	 * not to the policy total.
138	 */
139	const itemSurcharges = (items: Item[]): number =>
140	  items.reduce(
141	    (total, item) =>
142	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
143	    0,
144	  );
145	
146	const isLoyalCustomer = (customer: Customer): boolean =>
147	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
148	
149	/**
150	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
151	 * amount added to (or, when negative, subtracted from) that base premium, so
152	 * modifiers stack additively rather than compounding.
153	 */
154	const policyModifierRates = (
155	  customer: Customer,
156	  isFollowUpContract: boolean,
157	): number[] => [
158	  FIRST_INSURANCE_SURCHARGE,
159	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
160	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
161	];
162	
163	const policyModifiers = (
164	  basePremium: number,
165	  customer: Customer,
166	  isFollowUpContract: boolean,
167	): number =>
168	  policyModifierRates(customer, isFollowUpContract).reduce(
169	    (total, rate) => total + basePremium * rate,
170	    0,
171	  );
172	
173	const quotePremium = (
174	  step: QuoteStep,
175	  customer: Customer,
176	  isFollowUpContract: boolean,
177	): number => {
178	  const basePremium = policyBasePremium(step.items);
179	
180	  return roundUp(
181	    basePremium +
182	      itemSurcharges(step.items) +
183	      policyModifiers(basePremium, customer, isFollowUpContract) +
184	      PROCESSING_FEE,
185	  );
186	};
187	
188	/**
189	 * Every contract after the customer's first is a follow-up. Only quote steps
190	 * create contracts, so this counts preceding quotes rather than preceding steps.
191	 */
192	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
193	  precedingSteps.some((step) => step.op === "quote");
194	
195	/** Payouts are rounded down (in the MHPCO's favour), ignoring float noise. */
196	const roundDown = (amount: number): number =>
197	  Math.floor(Number(amount.toFixed(6)));
198	
199	/** The insurance sum is the sum of the items' insurance values. */
200	const insuranceSum = (items: Item[]): number =>
201	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
202	
203	const damagePayout = (damage: Damage): number =>
204	  Math.max(0, damage.amount - DEDUCTIBLE);
205	
206	const claimResult = (step: ClaimStep, policy: QuoteStep): ClaimResult => {
207	  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
208	  const payout = roundDown(
209	    step.incident.damages.reduce((total, damage) => total + damagePayout(damage), 0),
210	  );
211	
212	  return { payout, remainingCap: cap - payout };
213	};
214	
215	export const runScenario = (scenario: Scenario): ScenarioResults => ({
216	  results: scenario.steps.map((step, index) =>
217	    step.op === "quote"
218	      ? {
219	          premium: quotePremium(
220	            step,
221	            scenario.customer,
222	            isFollowUpContract(scenario.steps.slice(0, index)),
223	          ),
224	        }
225	      : claimResult(step, scenario.steps[step.policy] as QuoteStep),
226	  ),
227	});
